// Pour chaque incident P1 Jira terminé sans REX : chronologie (commentaires), durée,
// et masquage des données sensibles avant l'envoi au modèle.
const dejaRediges = new Set(
  $('Lire les REX existants').all()
    .map((i) => (i.json.fields || i.json).Incident) // Airtable « Search » : { id, fields: { Incident } }
    .filter(Boolean)
);

// Texte brut d'un document ADF (format des descriptions et commentaires Jira Cloud).
const adf = (n) => {
  if (!n) return '';
  if (typeof n === 'string') return n;
  if (n.type === 'text') return n.text || '';
  if (n.type === 'hardBreak') return '\n';
  const s = (n.content || []).map(adf).join('');
  return ['paragraph', 'heading', 'listItem', 'codeBlock'].includes(n.type) ? s + '\n' : s;
};

// Masque adresses IP et secrets passés en clair, comme côté ServiceNow.
const masquer = (t) => String(t || '')
  .replace(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g, '[IP]')
  .replace(/\b(password|passwd|pwd|mot de passe|token|secret)(\s*[:=]\s*)\S+/gi, '$1$2[MASQUÉ]')
  .replace(/(--pass(?:word)?[=\s]+)\S+/gi, '$1[MASQUÉ]')
  .replace(/(\s-p)(?=\S)\S+/g, '$1[MASQUÉ]');

const out = [];
for (const { json: page } of $input.all()) {
  for (const issue of page.issues || []) {
    const f = issue.fields || {};
    if (!issue.key || dejaRediges.has(issue.key)) continue;

    const commentaires = (f.comment?.comments || [])
      .slice()
      .sort((a, b) => String(a.created).localeCompare(String(b.created)));

    // Les intervenants deviennent « Intervenant 1, 2… » : aucun nom n'est envoyé au modèle.
    const alias = {};
    const pseudo = (u) => (alias[u] ||= `Intervenant ${Object.keys(alias).length + 1}`);

    const chronologie = commentaires
      .map((c) => `${c.created}, ${pseudo(c.author?.accountId || c.author?.displayName || '?')} : ${masquer(adf(c.body).trim())}`)
      .join('\n');

    // Fin de l'incident : date de résolution si le workflow Jira la renseigne,
    // sinon date de passage dans la catégorie « Terminé ».
    const fin = f.resolutiondate || f.statuscategorychangedate;

    out.push({ json: {
      sys_id: issue.key,
      number: issue.key,
      short_description: masquer(f.summary),
      description: masquer(adf(f.description).trim()),
      chronologie: chronologie || 'Aucun commentaire.',
      duree: Math.round((new Date(fin) - new Date(f.created)) / 60000),
      nbNotes: commentaires.length,
    }});
  }
}
return out;
